@js:
sort =[];
function push(title,url,type1,type2){
	var item ={title:title,url:url};
	if (type1!==undefined&&type2!==undefined){
		item.style={
			layout_flexGrow:type1,
			layout_flexBasisPercent:type2
		}
	}
	sort.push(item)
};
const page="/{{page}}.html";
const groups=[{
	prefix:"❶",
	types:["更新","点击"],
	typeUrls:["/fictions","/fictions/sort-read"]
}];
const tags=[
	"编辑推荐","人妻女友","学生校园","伴侣交换","都市生活",
	"动漫游戏","名人明星","经验故事","古典玄幻","家庭乱伦",
	"多人群交","公司职场","露出暴露","强暴性虐","西方主题",
	"同性主题","绿帽主题","长篇连载","经典回忆","有声小说"
];
const lengths=[{
	name:"短篇",
	suffix:"/length-1"
},{
	name:"中篇",
	suffix:"/length-2"
},{
	name:"长篇",
	suffix:"/length-3"
}];
groups.forEach(group=>{
	group.types.forEach((type,typeIndex)=>{
		const typeUrl=group.typeUrls[typeIndex];
		push(group.prefix+type,typeUrl+page,1,1);
		lengths.forEach(len=>{
			const lenUrl=typeUrl+len.suffix;
			push("❷"+len.name,lenUrl+page,1,1);
			tags.forEach(tag=>{
				const tagUrl=typeUrl+"/tag-"+tag+len.suffix;
				push(tag,tagUrl+page);
			});
		});
	});
});
JSON.stringify(sort)

ruleToc.chapterList:
ol li
@js:
var list=[],links=result.select("a"),regex=/(\w+-\w+)(?==")/g;
for (i=0;i<links.length;i++){
	link=links[i];
	aAttrs=String(link).match(regex);
	var text='',decUrl='';
	for (key of aAttrs){
		value=link.attr(key);
		value.includes("L2J")?decUrl=java.base64Decode(value):text=value.trim()
	}
	liAttrs=String(result[i]).match(regex);
	list.push({
		text:text,
		href:decUrl,
		num:result[i].attr(liAttrs[1])
	});
}
list.sort((a,b)=>a.num-b.num)

